css:
/* Modern Typography & Variables */
.invoice-wrapper {
    font-family: 'Inter', -apple-system, sans-serif;
    color: #2d3436;
    padding: 20px;
}

/* Header with Accent */
.invoice-header {
    display: flex;
    justify-content: space-between;
    border-bottom: 4px solid #0984e3;
    padding-bottom: 20px;
    margin-bottom: 30px;
}

.brand-name {
    font-size: 28px;
    font-weight: 900;
    color: #0984e3;
    text-transform: uppercase;
}

/* Color-Coded Cards */
.details-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 20px;
    margin-bottom: 30px;
}

.card {
    border-radius: 12px;
    padding: 20px;
    border: 1px solid rgba(0,0,0,0.05);
    transition: transform 0.2s;
}

/* Interactive Box Colors */
.tenant-box {
    background-color: #ebf5ff; /* Soft Blue */
    border-left: 6px solid #3498db;
}

.occupancy-box {
    background-color: #fff4e6; /* Soft Orange */
    border-left: 6px solid #e67e22;
}

.card-label {
    font-size: 11px;
    font-weight: 800;
    text-transform: uppercase;
    color: rgba(0,0,0,0.4);
    margin-bottom: 10px;
    display: block;
}

.card-value {
    font-size: 18px;
    font-weight: 700;
    color: #2d3436;
}

/* High-Contrast Financial Bar */
.total-bar {
    background: linear-gradient(135deg, #2d3436 0%, #000000 100%);
    color: #ffffff;
    border-radius: 12px;
    padding: 30px;
    display: flex;
    justify-content: space-between;
    align-items: center;
    box-shadow: 0 10px 20px rgba(0,0,0,0.1);
}

.amount-group .label {
    color: #b2bec3;
    font-size: 13px;
}

.final-amount {
    font-size: 36px;
    font-weight: 800;
    color: #00cec9; /* Bright Teal for the final number */
}

/* Amount Breakdown */
.breakdown {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 30px;
}

.breakdown td {
    padding: 10px 4px;
    border-bottom: 1px solid #dfe6e9;
}

.breakdown .amt {
    text-align: right;
    font-weight: 600;
}

.breakdown .total-row td {
    font-weight: 800;
    border-bottom: 2px solid #2d3436;
}

/* Pay online */
.pay-online {
    display: flex;
    gap: 20px;
    align-items: center;
    margin-top: 24px;
    padding: 16px 20px;
    border: 1px dashed #b2bec3;
    border-radius: 12px;
}

.pay-qr {
    width: 140px;
    height: 140px;
}
